import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.CDEKL17z.js";const u=JSON.parse('{"title":"Security model","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md"}'),s={name:"guide/security.md"};function n(i,e,l,d,h,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h1><p>The design assumption everywhere: the chat endpoint faces <strong>strangers</strong>. The embed key is public, the Origin header is forgeable off-browser, and the visitor is anonymous. Every control is chosen to hold under those conditions.</p><h2 id="the-layers" tabindex="-1">The layers <a class="header-anchor" href="#the-layers" aria-label="Permalink to &quot;The layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>What it stops</th><th>Holds against curl?</th></tr></thead><tbody><tr><td>Origin allowlist</td><td>Other sites embedding your bot</td><td>No - browser-enforced scoping only</td></tr><tr><td>Server-minted sessions</td><td>Client-invented identities</td><td>Yes</td></tr><tr><td>Per-session / per-IP rate limits</td><td>Bursts and floods</td><td>Partially (see proxy note)</td></tr><tr><td>Session-minting cap per tenant/day</td><td>Table-bloat via header rotation</td><td>Yes</td></tr><tr><td><strong>Daily message cap per tenant</strong></td><td><strong>The bill</strong></td><td><strong>Yes - this is the real backstop</strong></td></tr></tbody></table><p>Isolation between tenants is enforced by Postgres itself: composite foreign keys make a message that points at another tenant&#39;s conversation physically impossible, not just filtered out.</p><h2 id="the-reverse-proxy-rule" tabindex="-1">The reverse-proxy rule <a class="header-anchor" href="#the-reverse-proxy-rule" aria-label="Permalink to &quot;The reverse-proxy rule&quot;">​</a></h2><p>The quickstart binds to <code>127.0.0.1</code> on purpose. Anything public needs a reverse proxy (Caddy, nginx, Cloudflare Tunnel) that terminates TLS <strong>and sets <code>x-real-ip</code></strong> - without a trusted proxy, the per-IP limit can be defeated by spoofing that header. The daily cap bounds the bill either way; the proxy is what makes per-IP limiting meaningful.</p><h2 id="prompt-injection-honestly" tabindex="-1">Prompt injection, honestly <a class="header-anchor" href="#prompt-injection-honestly" aria-label="Permalink to &quot;Prompt injection, honestly&quot;">​</a></h2><p>The prompt has three trust levels: a fixed platform preamble, the tenant persona (delimited, cannot override the preamble), and tool results (marked as third-party data, never folded into the system prompt). None of this is a hard boundary against a determined injector - the real invariant is that <strong>nothing sensitive ever enters the model&#39;s context</strong>: no keys, no internal hostnames, no other tenant&#39;s data. Assume the whole prompt is public, because effectively it is.</p><h2 id="rules-that-look-like-limitations-but-aren-t" tabindex="-1">Rules that look like limitations but aren&#39;t <a class="header-anchor" href="#rules-that-look-like-limitations-but-aren-t" aria-label="Permalink to &quot;Rules that look like limitations but aren&#39;t&quot;">​</a></h2><ul><li><strong>Tenants cannot supply URLs.</strong> A free-form URL field would let a tenant aim this server at internal services (SSRF). Tools are platform-owned code packs; the single exception, the Slack webhook, is pinned to <code>hooks.slack.com</code>.</li><li><strong>The admin conversation viewer renders plain text.</strong> The operator&#39;s browser holds the session that controls the platform; visitor-authored markdown or HTML must never execute there.</li><li><strong>Admin login is rate limited</strong> (globally, not per-IP - see the proxy note above).</li></ul>',11)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
